-- Unassignable private employee material contributes a book-level blocker only.
CREATE FUNCTION accounting.closing_date_valid(value TEXT) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
 BEGIN
 IF value IS NULL OR length(value)<>10 OR value !~ '^20[0-9]{2}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN RETURN false; END IF;
 RETURN to_char(value::date,'YYYY-MM-DD')=value;
 EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
 END $$;
REVOKE ALL ON FUNCTION accounting.closing_date_valid(TEXT) FROM PUBLIC,accounting_worker;
GRANT EXECUTE ON FUNCTION accounting.closing_date_valid(TEXT) TO accounting_app;
CREATE OR REPLACE FUNCTION accounting.closing_fingerprint(target_book TEXT) RETURNS TEXT LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,accounting,pg_temp AS $$
 DECLARE basis JSONB; BEGIN
 IF NOT accounting.ai_book_reviewer(target_book) THEN RAISE EXCEPTION 'current scoped book reviewer required' USING ERRCODE='42501'; END IF;
 SELECT jsonb_build_object('books',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM books t WHERE t.id=b.id),'periods',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM periods t WHERE t.book_id=b.id),'sources',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM sources t WHERE t.book_id=b.id),'drafts',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM drafts t WHERE t.book_id=b.id),'draft_lines',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM draft_lines t WHERE t.book_id=b.id),'draft_line_auxiliaries',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM draft_line_auxiliaries t WHERE t.book_id=b.id),'accounts',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM accounts t WHERE t.book_id=b.id),'source_evidence',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM source_evidence t WHERE t.book_id=b.id),'business_mappings',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM business_mappings t WHERE t.book_id=b.id),'business_mapping_versions',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM business_mapping_versions t WHERE t.book_id=b.id),'business_events',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM business_events t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id AND (substr(jsonb_extract_path_text((t.payload)::jsonb,'occurred_on'),1,7)=b.period OR (t.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((t.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions m WHERE m.event_id=t.id AND m.book_id=b.id))),'business_attachments',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM business_attachments t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'case_tasks',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM case_tasks t WHERE t.book_id=b.id OR t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'case_responses',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM case_responses t WHERE t.case_id IN(SELECT c.id FROM case_tasks c WHERE c.book_id=b.id OR c.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))))),'case_supersessions',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM case_supersessions t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'ocr_jobs',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM ocr_jobs t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'proposal_jobs',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM proposal_jobs t WHERE t.book_id=b.id),'ai_runs',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM ai_runs t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'model_costs',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM model_costs t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'ai_findings',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM ai_findings t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'ai_finding_reviews',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM ai_finding_reviews t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on')))) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))),'ai_bank_links',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM ai_bank_links t WHERE t.book_id=b.id),'bank_import_keys',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM bank_import_keys t WHERE t.book_id=b.id),'bank_duplicate_decisions',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM bank_duplicate_decisions t WHERE t.book_id=b.id),'bank_source_dispositions',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM bank_source_dispositions t WHERE t.book_id=b.id),'exports',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM exports t WHERE t.book_id=b.id),'delivery_manifests',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM delivery_manifests t WHERE t.book_id=b.id),'delivery_receipts',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM delivery_receipts t WHERE t.book_id=b.id),'delivery_receipt_items',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM delivery_receipt_items t WHERE t.book_id=b.id),'fact_revisions',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM fact_revisions t WHERE t.old_book_id=b.id OR t.target_book_id=b.id),'fact_revision_lineage',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM fact_revision_lineage t WHERE t.old_book_id=b.id OR t.new_book_id=b.id),'company_master_entities',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM company_master_entities t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id),'company_master_aliases',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM company_master_aliases t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id),'journal_templates',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM journal_templates t WHERE t.book_id=b.id),'journal_template_versions',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM journal_template_versions t WHERE t.book_id=b.id),'learning_rules',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM learning_rules t WHERE t.book_id=b.id),'settlement_items',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM settlement_items t WHERE t.book_id=b.id),'settlement_allocations',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM settlement_allocations t WHERE t.book_id=b.id),'settlement_reversals',(SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM settlement_reversals t WHERE t.book_id=b.id)) INTO basis FROM accounting.books b WHERE b.id=target_book;
 RETURN encode(sha256(convert_to(basis::text,'UTF8')),'hex'); END $$;
CREATE OR REPLACE FUNCTION accounting.closing_issues(target_book TEXT) RETURNS TABLE(category TEXT,object_type TEXT,object_id TEXT,detail TEXT) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,accounting,pg_temp AS $$ BEGIN
 IF NOT accounting.ai_book_reviewer(target_book) THEN RAISE EXCEPTION 'current scoped book reviewer required' USING ERRCODE='42501'; END IF;
 RETURN QUERY
 WITH book AS (SELECT * FROM books WHERE id=target_book),
      active_sources AS (SELECT s.* FROM sources s JOIN book b ON b.id=s.book_id WHERE NOT EXISTS(SELECT 1 FROM bank_source_dispositions z WHERE z.book_id=s.book_id AND z.source_id=s.id) AND NOT EXISTS(SELECT 1 FROM fact_revision_lineage z WHERE z.old_book_id=s.book_id AND z.old_source_id=s.id)),
      active_drafts AS (SELECT d.* FROM drafts d JOIN active_sources s ON s.id=d.source_id AND s.book_id=d.book_id
        WHERE NOT EXISTS(SELECT 1 FROM ai_bank_links link WHERE link.bank_source_id=s.id AND link.book_id=s.book_id)),
      event_scope AS (SELECT e.*,b.id AS scope_book_id FROM business_events e JOIN book b ON b.firm_id=e.firm_id AND b.company_id=e.company_id
        WHERE substr(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'),1,7)=b.period OR EXISTS(SELECT 1 FROM business_mappings m WHERE m.event_id=e.id AND m.book_id=b.id)),
      issues AS (
      SELECT 'unreviewed' AS category,'draft' AS object_type,d.id AS object_id,'尚有未审核或未导出的有效凭证' AS detail FROM active_drafts d WHERE d.status<>'exported'
      UNION ALL SELECT 'unprocessed','source',s.id,'来源尚未形成有效凭证草稿' FROM active_sources s WHERE NOT EXISTS(SELECT 1 FROM drafts d WHERE d.book_id=s.book_id AND d.source_id=s.id)
      UNION ALL SELECT 'missing_evidence','source',s.id,'当前有效来源缺少原件或证据引用' FROM active_sources s WHERE trim(COALESCE((SELECT se.evidence_ref FROM source_evidence se WHERE se.book_id=s.book_id AND se.source_id=s.id ORDER BY se.id DESC LIMIT 1),s.evidence_ref))=''
      UNION ALL SELECT 'business_pending','book',b.id,'本企业本期仍有未完成审批或移交的业务事项，请企业财务核对' FROM book b WHERE EXISTS(SELECT 1 FROM event_scope e WHERE e.scope_book_id=b.id AND e.status<>'handed_off')
      UNION ALL SELECT 'missing_evidence','book',b.id,'本企业仍有发生日期缺失或无效的未移交资料，无法确定归期，请企业财务修正' FROM book b WHERE EXISTS(SELECT 1 FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND e.status<>'handed_off' AND NOT (accounting.closing_date_valid(jsonb_extract_path_text((e.payload)::jsonb,'occurred_on'))))
      UNION ALL SELECT 'missing_evidence','event',m.event_id,'已移交事项缺少当前有效附件' FROM business_mappings m JOIN book b ON b.id=m.book_id
        WHERE NOT EXISTS(SELECT 1 FROM business_attachments a WHERE a.event_id=m.event_id AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id))
      UNION ALL SELECT 'open_cases','case',c.id,'本账套仍有未关闭的异常或补件待办' FROM case_tasks c JOIN book b ON c.book_id=b.id OR c.event_id IN(SELECT m.event_id FROM business_mappings m WHERE m.book_id=b.id) WHERE c.state<>'closed'
      UNION ALL SELECT 'open_cases','book',b.id,'本企业本期未移交事项仍有待处理补件，请企业财务核对' FROM book b WHERE EXISTS(SELECT 1 FROM case_tasks c JOIN event_scope e ON e.id=c.event_id AND e.scope_book_id=b.id WHERE c.book_id IS NULL AND c.state<>'closed' AND NOT EXISTS(SELECT 1 FROM business_mappings m WHERE m.event_id=e.id AND m.book_id=b.id))
      UNION ALL SELECT 'background_pending','ocr_job',q.id,'票据识别仍在运行或存在发送结果未知的任务' FROM ocr_jobs q JOIN event_scope e ON e.id=q.event_id WHERE q.status IN ('queued','running','retry_wait') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=q.event_id AND z.old_attachment_id=q.attachment_id) AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT 'background_pending','proposal_job',q.id,'分录任务仍在运行或等待人工处理' FROM proposal_jobs q JOIN book b ON b.id=q.book_id WHERE q.status IN ('waiting','queued','running','retry_wait') OR q.status IN ('needs_attention','interrupted','failed') AND EXISTS(SELECT 1 FROM drafts d WHERE d.id=q.draft_id AND d.book_id=q.book_id AND d.status='draft')
      UNION ALL SELECT 'background_pending','event',r.event_id,'仍有未完成的模型执行记录' FROM ai_runs r JOIN event_scope e ON e.id=r.event_id WHERE r.status='running' AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT 'model_uncertain','event',c.event_id,'仍有模型外发结果或费用未知的记录' FROM model_costs c JOIN event_scope e ON e.id=c.event_id WHERE c.state='uncertain' AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT 'unmatched_bank','source',s.id,'银行来源未匹配业务事项，也未形成独立已导出的凭证' FROM active_sources s WHERE s.source_kind='bank' AND NOT EXISTS(SELECT 1 FROM ai_bank_links l WHERE l.bank_source_id=s.id AND l.book_id=s.book_id) AND NOT EXISTS(SELECT 1 FROM drafts d WHERE d.source_id=s.id AND d.book_id=s.book_id AND d.status='exported')
      UNION ALL SELECT 'unmatched_bank','source',s.id,'银行收付核销尚未分配完整金额，待清偿事项仍须核对' FROM active_sources s WHERE s.source_kind='bank'
        AND EXISTS(SELECT 1 FROM settlement_allocations a WHERE a.book_id=s.book_id AND a.bank_source_id=s.id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id AND r.book_id=a.book_id))
        AND (SELECT COALESCE(sum(a.amount_cents),0) FROM settlement_allocations a WHERE a.book_id=s.book_id AND a.bank_source_id=s.id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id AND r.book_id=a.book_id))<>s.amount_cents
      UNION ALL SELECT 'unmatched_business','event',m.event_id,'已支付业务事项尚未匹配银行来源，请先核对防止重复记账' FROM business_mappings m JOIN event_scope e ON e.id=m.event_id AND e.scope_book_id=m.book_id JOIN book b ON b.id=m.book_id
        WHERE jsonb_extract_path_text((e.payload)::jsonb,'payment_status')='paid' AND NOT EXISTS(SELECT 1 FROM ai_bank_links l WHERE l.event_id=m.event_id AND l.book_id=m.book_id)
        AND NOT EXISTS(SELECT 1 FROM fact_revision_lineage z WHERE z.old_book_id=m.book_id AND z.old_source_id=m.source_id)
      UNION ALL SELECT 'delivery_pending','export',x.id,'导出后缺少内容一致的完整导入回执，或回执仍有未知及差异' FROM exports x JOIN book b ON b.id=x.book_id WHERE NOT EXISTS(SELECT 1 FROM delivery_manifests m JOIN delivery_receipts r ON r.export_id=m.export_id AND r.book_id=m.book_id
      WHERE m.export_id=x.id AND m.book_id=x.book_id AND jsonb_extract_path_text((r.body_json)::jsonb,'book_id')=jsonb_extract_path_text((m.payload_json)::jsonb,'book_id') AND jsonb_extract_path_text((r.body_json)::jsonb,'company_id')=jsonb_extract_path_text((m.payload_json)::jsonb,'company_id') AND jsonb_extract_path_text((r.body_json)::jsonb,'period')=jsonb_extract_path_text((m.payload_json)::jsonb,'period') AND jsonb_extract_path_text((r.body_json)::jsonb,'currency')=jsonb_extract_path_text((m.payload_json)::jsonb,'currency')
      AND NOT EXISTS(SELECT 1 FROM delivery_receipts newer WHERE newer.export_id=r.export_id AND newer.book_id=r.book_id AND (newer.created_at>r.created_at OR newer.created_at=r.created_at AND newer.id>r.id))
      AND (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((r.body_json)::jsonb,'items')) i(value))=(SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((m.payload_json)::jsonb,'items')) expected(value))
      AND (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((r.body_json)::jsonb,'items')) i(value))=x.count
      AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_extract_path((r.body_json)::jsonb,'items')) i(value)
        WHERE jsonb_extract_path_text((i.value)::jsonb,'status') IS NULL OR jsonb_extract_path_text((i.value)::jsonb,'status')<>'accepted' OR trim(COALESCE(jsonb_extract_path_text((i.value)::jsonb,'external_voucher_id'),''))=''
        OR (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((r.body_json)::jsonb,'items')) duplicate(value) WHERE jsonb_extract_path_text((duplicate.value)::jsonb,'draft_id')=jsonb_extract_path_text((i.value)::jsonb,'draft_id'))<>1
        OR (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((r.body_json)::jsonb,'items')) duplicate(value) WHERE jsonb_extract_path_text((duplicate.value)::jsonb,'external_voucher_id')=jsonb_extract_path_text((i.value)::jsonb,'external_voucher_id'))<>1
        OR EXISTS(SELECT 1 FROM delivery_receipt_items h WHERE h.book_id=r.book_id AND h.receipt_id<>r.id AND
          (h.claimed_draft_id<>jsonb_extract_path_text((i.value)::jsonb,'draft_id') AND h.external_voucher_id=jsonb_extract_path_text((i.value)::jsonb,'external_voucher_id')
           OR h.claimed_draft_id=jsonb_extract_path_text((i.value)::jsonb,'draft_id') AND trim(COALESCE(h.external_voucher_id,''))<>'' AND h.external_voucher_id<>jsonb_extract_path_text((i.value)::jsonb,'external_voucher_id')))
        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_extract_path((m.payload_json)::jsonb,'items')) expected(value) WHERE jsonb_extract_path_text((expected.value)::jsonb,'draft_id')=jsonb_extract_path_text((i.value)::jsonb,'draft_id') AND (jsonb_extract_path_text((i.value)::jsonb,'date')) IS NOT DISTINCT FROM (jsonb_extract_path_text((expected.value)::jsonb,'date')) AND (jsonb_extract_path_text((i.value)::jsonb,'amount')) IS NOT DISTINCT FROM (jsonb_extract_path_text((expected.value)::jsonb,'amount')) AND (jsonb_extract_path_text((i.value)::jsonb,'description')) IS NOT DISTINCT FROM (jsonb_extract_path_text((expected.value)::jsonb,'description'))
          AND (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((i.value)::jsonb,'lines')) line(value))=(SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((expected.value)::jsonb,'lines')) wanted(value))
          AND (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((i.value)::jsonb,'lines')) line(value))>=2
          AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_extract_path((i.value)::jsonb,'lines')) line(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_extract_path((expected.value)::jsonb,'lines')) wanted(value)
            WHERE (jsonb_extract_path_text((line.value)::jsonb,'ordinal')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'ordinal')) AND (jsonb_extract_path_text((line.value)::jsonb,'account_code')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'account_code')) AND (jsonb_extract_path_text((line.value)::jsonb,'debit')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'debit')) AND (jsonb_extract_path_text((line.value)::jsonb,'credit')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'credit')) AND jsonb_typeof(line.value->'auxiliary_values')='object' AND (jsonb_extract_path_text((line.value)::jsonb,'auxiliary_values','department')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'auxiliary_values','department')) AND (jsonb_extract_path_text((line.value)::jsonb,'auxiliary_values','employee')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'auxiliary_values','employee')) AND (jsonb_extract_path_text((line.value)::jsonb,'auxiliary_values','counterparty')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'auxiliary_values','counterparty')) AND (jsonb_extract_path_text((line.value)::jsonb,'auxiliary_values','project')) IS NOT DISTINCT FROM (jsonb_extract_path_text((wanted.value)::jsonb,'auxiliary_values','project')) AND line.value->'auxiliary_values'=wanted.value->'auxiliary_values')
            OR (SELECT count(*) FROM jsonb_array_elements(jsonb_extract_path((i.value)::jsonb,'lines')) duplicate_line(value) WHERE jsonb_extract_path_text((duplicate_line.value)::jsonb,'ordinal')=jsonb_extract_path_text((line.value)::jsonb,'ordinal'))<>1)))
    )
      UNION ALL SELECT 'fact_revision','revision',r.id,'业务事实修订或已导出调整建议尚未完成独立处置' FROM fact_revisions r JOIN book b ON r.old_book_id=b.id OR r.target_book_id=b.id WHERE r.state IN ('pending','adjustment_proposed')
      ) SELECT issues.category,issues.object_type,issues.object_id,issues.detail FROM issues ORDER BY issues.category,issues.object_type,issues.object_id; END $$;
